declarations.formal_type:
∀ {G : Type u_1} [inst : Group.{u_1} G] {V : Type u_2} [inst_1 : AddCommGroup.{u_2} V]
  [inst_2 : Module.{0, u_2} Complex V] {K : Type u_3} {S : Type u_4} [inst_3 : Group.{u_3} K] [inst_4 : Group.{u_4} S]
  (fφ : MonoidHom.{u_4, u_1} S G) (τ' : Representation.{0, u_4, u_2} Complex S V) (f : MonoidHom.{u_3, u_1} K G)
  (σ : MonoidHom.{u_4, u_3} S K) (τ : Representation.{0, u_3, u_2} Complex K V),
  Eq.{max (u_1 + 1) (u_4 + 1)} fφ (MonoidHom.comp.{u_4, u_3, u_1} f σ) →
    Eq.{max (u_2 + 1) (u_4 + 1)} τ' (MonoidHom.comp.{u_4, u_3, u_2} τ σ) →
      Function.Bijective.{u_4 + 1, u_3 + 1} (DFunLike.coe.{max (u_3 + 1) (u_4 + 1), u_4 + 1, u_3 + 1} σ) →
        Eq.{max (u_1 + 1) (u_2 + 1)}
          (Representation.Coinvariants.ker.{0, u_4, max u_1 u_2}
            (Representation.tprod.{0, u_4, u_1, u_2}
              (MonoidHom.comp.{u_4, u_1, u_1} (Representation.leftRegular.{0, u_1} Complex G) fφ) τ'))
          (Representation.Coinvariants.ker.{0, u_3, max u_1 u_2}
            (Representation.tprod.{0, u_3, u_1, u_2}
              (MonoidHom.comp.{u_3, u_1, u_1} (Representation.leftRegular.{0, u_1} Complex G) f) τ))

∀ {G : Type u_1} [inst : Group.{u_1} G] {V : Type u_2} [inst_1 : AddCommGroup.{u_2} V]
  [inst_2 : Module.{0, u_2} Complex V] {S : Type u_3} {H : Type u_4} [inst_3 : Group.{u_3} S] [inst_4 : Group.{u_4} H]
  (φ : MonoidHom.{u_3, u_4} S H) (ψ : MonoidHom.{u_4, u_1} H G) (τ : Representation.{0, u_3, u_2} Complex S V),
  Exists.{max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1)} fun e =>
    ∀ (g : G) (x : Representation.IndV.{0, u_4, u_1, max u_2 u_4} ψ (Representation.ind.{0, u_3, u_4, u_2} φ τ)),
      Eq.{max (u_1 + 1) (u_2 + 1)}
        (DFunLike.coe.{max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1), max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1),
            max (u_1 + 1) (u_2 + 1)}
          e
          (DFunLike.coe.{max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1), max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1),
              max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1)}
            (DFunLike.coe.{max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1), u_1 + 1, max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1)}
              (Representation.ind.{0, u_4, u_1, max u_2 u_4} ψ (Representation.ind.{0, u_3, u_4, u_2} φ τ)) g)
            x))
        (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), max (u_1 + 1) (u_2 + 1), max (u_1 + 1) (u_2 + 1)}
          (DFunLike.coe.{max (u_1 + 1) (u_2 + 1), u_1 + 1, max (u_1 + 1) (u_2 + 1)}
            (Representation.ind.{0, u_3, u_1, u_2} (MonoidHom.comp.{u_3, u_4, u_1} ψ φ) τ) g)
          (DFunLike.coe.{max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1), max (max (u_1 + 1) (u_2 + 1)) (u_4 + 1),
              max (u_1 + 1) (u_2 + 1)}
            e x))
